135	     *  sheet's today changes. A claim that is not a DRAFT, is dated in a closed period, or is locked
136	     *  by another user's editor is refused and takes no lock. */
137	    @Transactional
138	    public Claim lock(String sheetId, String user, Long personId, Long id) {
139	        person(sheetId, personId);
140	        // Lock the sheet first, so two users opening the editor at the same moment take turns.
141	        sheets.lock(sheetId);
142	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
143	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
144	        if (claim.getStatus() != ClaimStatus.DRAFT) {
145	            throw new ClaimNotEditableException(claim.getStatus());
146	        }
147	        refuseClosed(sheetId, claim.getDate());
148	        if (claim.lockedAgainst(user)) {
149	            throw new ClaimLockedException(claim.getLockedBy());
150	        }
151	        claim.setLockedBy(user);
152	        return claims.saveAndFlush(claim);
