175	    /** Move a claim to a new status; a change its status does not allow, or one the sheet's
176	     *  permission matrix does not let the user's role make, is refused, as is the user who opened a
177	     *  claim settling it. A clerk settling a claim whose due is above the clerk limit
178	     *  leaves it PENDING a steward's approval instead. */
179	    @Transactional
180	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
181	        Person person = person(sheetId, personId);
182	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
183	        // read below is its latest state.
184	        if (to == ClaimStatus.OPEN) {
185	            sheets.lock(sheetId);
186	        }
187	        Claim claim = claim(sheetId, personId, id);
188	        settings.refuseUnless(sheetId, user, switch (to) {
189	            case OPEN -> Permission.OPEN;
190	            case SETTLED -> Permission.SETTLE;
191	            case VOID -> Permission.VOID;
192	            case DRAFT, PENDING -> throw new StatusChangeRefusedException(claim.getStatus(), to);
193	        });
194	        refuseClosed(sheetId, claim.getDate());
195	        // A SETTLED claim is voided only by a steward, within the void window of its settlement.
196	        boolean reversing = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
197	        if (reversing) {
198	            refuseLateOrUnstewardedVoid(sheetId, user, claim);
199	        } else if (!claim.getStatus().canMoveTo(to)) {
200	            throw new StatusChangeRefusedException(claim.getStatus(), to);
201	        }
202	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
203	            throw new OwnClaimSettleRefusedException(user);
204	        }
205	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
206	            throw new StatusChangeRefusedException(claim.getStatus(), to);
207	        }
208	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
209	        // gathered by then.
210	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
211	        if (to == ClaimStatus.SETTLED) {
212	            refuseUnproved(sheetId, claim, due);
213	        }
214	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
215	            to = ClaimStatus.PENDING;
216	        }
217	        claim.setStatus(to);
218	        if (to == ClaimStatus.OPEN) {
219	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
220	            claim.setOpenedBy(user);
221	        } else if (to == ClaimStatus.SETTLED) {
222	            claim.setSettledDue(due);
223	        }
224	        Claim saved = claims.saveAndFlush(claim);
225	        log(sheetId, user, person, saved);
226	        String event = switch (to) {
227	            case OPEN -> "CLAIM_OPENED";
228	            case PENDING -> "CLAIM_PENDING";
229	            case SETTLED -> "CLAIM_SETTLED";
230	            case VOID -> "CLAIM_VOIDED";
231	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
232	        };
233	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
234	        if (to == ClaimStatus.SETTLED) {
235	            line += " due=" + settledDueText(saved);
236	        } else if (reversing) {
237	            line += " reversed=" + settledDueText(saved);
238	        }
239	        audit.recordOnCommit(line);
240	        if (to == ClaimStatus.SETTLED) {
241	            notifyWatchers(sheetId, user, person, saved);
242	        }
243	        return saved;
244	    }
