271	    /** Split an amount off an OPEN claim: it keeps the rest of its amount and loses any figure a
272	     *  statement bound it to, and a new OPEN claim of the split-off amount, with the same date and
273	     *  note, the next number, opened by the user and due by its date plus the terms in force on it,
274	     *  is listed under the person naming the claim it was split from. A claim that is not OPEN, one
275	     *  deferred, one dated in a closed period, an amount not above 0.00 and below the claim's, or a
276	     *  user whose role may not open a claim, is refused. */
277	    @Transactional
278	    public Split split(String sheetId, String user, Long personId, Long id, BigDecimal amount) {
279	        Person person = person(sheetId, personId);
280	        // Lock the sheet first, as opening does: the new claim takes the next number.
281	        sheets.lock(sheetId);
282	        Claim claim = claim(sheetId, personId, id);
283	        settings.refuseUnless(sheetId, user, Permission.OPEN);
284	        refuseClosed(sheetId, claim.getDate());
285	        if (claim.getStatus() != ClaimStatus.OPEN || claim.deferredOn(sheets.today(sheetId))) {
286	            throw new SplitRefusedException("A " + claim.getStatus() + " claim cannot be split");
287	        }
288	        BigDecimal part = scaled(amount);
289	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
290	            throw new SplitRefusedException("A claim is split by an amount above 0.00 and below its own");
291	        }
292	        claim.setAmount(claim.getAmount().subtract(part));
293	        claim.unbind();
294	        Claim kept = claims.saveAndFlush(claim);
295	        LocalDate on = kept.getDate();
296	        LocalDate dueBy = on.plusDays(termsFor(sheetId, person, on));
297	        Claim added = claims.saveAndFlush(Claim.splitOff(kept, part, dueBy, nextNumber(sheetId, on), user));
298	        log(sheetId, user, person, added);
299	        audit.recordOnCommit(line("CLAIM_SPLIT", sheetId, user, person, kept, kept.getNumber())
300	                + " into=" + added.getNumber());
301	        record("CLAIM_OPENED", sheetId, user, person, added);
302	        return new Split(kept, added);
303	    }
