357	
358	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
359	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
360	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
361	     *  one dated in a closed period, is refused. */
362	    @Transactional
363	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
364	        Person person = person(sheetId, personId);
365	        Claim claim = claim(sheetId, personId, id);
366	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
367	            throw new ResettleRefusedException(user);
368	        }
369	        if (claim.getStatus() != ClaimStatus.SETTLED) {
370	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
371	        }
372	        refuseClosed(sheetId, claim.getDate());
373	        String old = settledDueText(claim);
374	        BigDecimal figure = liveFigureOf(sheetId, person, claim);
375	        claim.setSettledDue(figure == null ? null : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, claim, figure, true))));
376	        Claim saved = claims.saveAndFlush(claim);
377	        log(sheetId, user, person, saved);
378	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
379	                + " old=" + old + " new=" + settledDueText(saved));
380	        notifyWatchers(sheetId, user, person, saved);
381	        return saved;
382	    }
383	
384	    /** A user whose role the sheet's permission matrix lets reassign (by the standing rule a steward)
385	     *  moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
386	     *  number and date, loses any figure a statement bound it to (live again until its new person's
387	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
388	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
389	     *  a move to the same person or to one retired before the claim's date, is refused. */
390	    @Transactional
391	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
392	        Person from = person(sheetId, personId);
393	        Person to = person(sheetId, toPersonId);
394	        Claim claim = claim(sheetId, personId, id);
395	        if (!settings.allows(sheetId, user, Permission.REASSIGN)) {
396	            throw new ReassignRefusedException(user);
397	        }
398	        if (!claim.getStatus().canReassign()) {
399	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
400	        }
401	        if (from.getId().equals(to.getId())) {
402	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
403	        }
404	        if (claim.isCorrection()) {
405	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
406	        }
407	        refuseClosed(sheetId, claim.getDate());
408	        refuseRetired(to, claim.getDate());
409	        claim.setPersonId(to.getId());
410	        claim.unbind();
411	        claims.saveAndFlush(claim);
412	        claims.relist(claim.getId());
413	        Claim saved = claim(sheetId, to.getId(), id);
414	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
415	                + " from=" + from.getName() + " to=" + to.getName());
416	        return saved;
417	    }
418	
419	    /** A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and any figure a
420	     *  statement bound it to stays bound; its period follows the new date, and under period numbering
421	     *  a claim whose period changes takes the next number of its new period, its old number never
422	     *  given again. Anyone but a steward, a claim that is not OPEN or PENDING, a claim dated in a
423	     *  closed period or a new date inside one, or a new date after its person's retirement, is refused. */
424	    @Transactional
425	    public Claim redate(String sheetId, String user, Long personId, Long id, LocalDate date) {
426	        Person person = person(sheetId, personId);
427	        // Lock the sheet first, as opening does: the claim may take the next number.
428	        sheets.lock(sheetId);
429	        Claim claim = claim(sheetId, personId, id);
430	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
431	            throw new RedateForbiddenException(user);
432	        }
433	        if (!claim.getStatus().isOpen()) {
434	            throw new RedateRefusedException("A " + claim.getStatus() + " claim cannot be re-dated");
435	        }
436	        refuseClosed(sheetId, claim.getDate());
437	        refuseClosed(sheetId, date);
438	        refuseRetired(person, date);
439	        LocalDate old = claim.getDate();
440	        if (periodNumbering(sheetId) && !periodPrefixOf(sheetId, old).equals(periodPrefixOf(sheetId, date))) {
441	            String was = claim.getNumber();
442	            claim.setNumber(nextNumber(sheetId, date));
443	            if (was != null) {
444	                claims.retireNumber(sheetId, was);
445	            }
446	        }
447	        claim.setDate(date);
448	        Claim saved = claims.saveAndFlush(claim);
449	        audit.recordOnCommit(line("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber())
450	                + " old=" + old + " new=" + date);
451	        return saved;
452	    }
453	
454	    /** A claim's status log, oldest first: one line per status it has had. */
455	    public List<String> logOf(Long claimId) {
456	        return logs.findByClaimIdOrderByIdAsc(claimId).stream().map(ClaimLogEntry::text).toList();
457	    }
458	
459	    /** The status logs of the sheet's claims by claim id, each oldest first. */
460	    public Map<Long, List<String>> logsOf(String sheetId) {
461	        return logs.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
462	                ClaimLogEntry::getClaimId, Collectors.mapping(ClaimLogEntry::text, Collectors.toList())));
463	    }
464	
465	    /** The status each of the sheet's claims had at the end of a day, by claim id, as its status log
466	     *  records it: the last status it moved to on or before that day. A claim added after it has none. */
467	    public Map<Long, ClaimStatus> statusesAsOf(String sheetId, LocalDate day) {
468	        Map<Long, ClaimStatus> statuses = new HashMap<>();
469	        for (ClaimLogEntry entry : logs.findBySheetIdOrderByIdAsc(sheetId)) {
470	            if (!entry.getOn().isAfter(day)) {
471	                statuses.put(entry.getClaimId(), entry.getStatus());
472	            }
473	        }
474	        return statuses;
475	    }
476	
477	    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
478	     *  its due as it is now. */
479	    private void log(String sheetId, String user, Person person, Claim claim) {
480	        BigDecimal due = dueOf(sheetId, person, claim);
481	        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
482	                due != null ? due.toPlainString() : NO_RATE));
483	    }
484	
485	    /** A SETTLED claim is voided only by a steward, and only while the sheet's today is within
486	     *  {@value #VOID_WINDOW_DAYS} days of the date its status log last records it SETTLED. */
487	    private void refuseLateOrUnstewardedVoid(String sheetId, String user, Claim claim) {
488	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
489	            throw new VoidRefusedException(user + " is not a steward: only a steward voids a settled claim");
490	        }
491	        LocalDate settledOn = logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
492	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
493	                .map(ClaimLogEntry::getOn)
494	                .reduce((first, last) -> last)
495	                .orElseThrow(() -> new VoidRefusedException("Claim " + claim.getId() + " has no settlement"));
496	        if (sheets.today(sheetId).isAfter(settledOn.plusDays(VOID_WINDOW_DAYS))) {
497	            throw new VoidRefusedException("A settled claim is voided within " + VOID_WINDOW_DAYS
498	                    + " days of its settlement on " + settledOn);
499	        }
500	    }
501	
502	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
503	     *  closed period, or the user is not a steward. */
504	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
505	        Claim claim = claim(sheetId, personId, id);
506	        refuseClosed(sheetId, claim.getDate());
507	        if (claim.getStatus() != ClaimStatus.PENDING) {
508	            throw new StatusChangeRefusedException(claim.getStatus(), to);
509	        }
510	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
511	            throw new ApprovalRefusedException(user);
512	        }
513	        return claim;
514	    }
515	
516	    private Claim claim(String sheetId, Long personId, Long id) {
517	        return claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
518	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
519	    }
520	
521	    private static String settledDueText(Claim claim) {
522	        return claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : NO_RATE;
523	    }
524	
525	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
526	     *  after it) the next within the period its date falls in, <period>-<n>, or X-<n> when it falls
527	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
528	    private String nextNumber(String sheetId, LocalDate date) {
529	        if (!periodNumbering(sheetId)) {
530	            return String.valueOf(sheets.nextClaimNumber(sheetId));
531	        }
532	        String prefix = periodPrefixOf(sheetId, date);
533	        long last = Stream.concat(claims.numbers(sheetId).stream(), claims.retiredNumbers(sheetId).stream())
534	                .filter(number -> number.startsWith(prefix))
535	                .map(number -> number.substring(prefix.length()))
536	                .filter(n -> n.matches("\\d{1,18}"))
537	                .mapToLong(Long::parseLong)
538	                .max().orElse(0);
539	        return prefix + (last + 1);
540	    }
541	
542	    /** Whether period numbering is on: set, and the sheet's today on or after it. */
543	    private boolean periodNumbering(String sheetId) {
544	        LocalDate from = settings.periodNumberingFrom(sheetId);
545	        return from != null && !sheets.today(sheetId).isBefore(from);
546	    }
547	
548	    /** The prefix a period number of a claim dated on a date takes: <period>- or X-. */
549	    private String periodPrefixOf(String sheetId, LocalDate date) {
550	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
551	                .filter(period -> period.contains(date))
552	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
553	    }
554	
555	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
556	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
557	     *  person's grade rate; null when it has none. */
558	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
559	        if (claim.getSettledDue() != null) {
560	            return claim.getSettledDue();
561	        }
562	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : liveFigureOf(sheetId, person, claim);
563	    }
564	
565	    /** The due a claim shows: a settled claim's frozen due; otherwise the greater of the sheet's floor in
566	     *  force on its date (none for a correction) and its figure plus its late charge (none while it is
567	     *  deferred: it is not overdue then); null when it has no figure. */
568	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
569	        if (claim.getSettledDue() != null) {
570	            return claim.getSettledDue();
571	        }
572	        BigDecimal figure = figureOf(sheetId, person, claim);
573	        boolean open = claim.getStatus().isOpen() && !claim.deferredOn(sheets.today(sheetId));
574	        return figure == null ? null : floored(sheetId, claim, figure.add(lateChargeOf(sheetId, claim, figure, open)));
575	    }
576	
577	    /** A due raised to the sheet's floor in force on the claim's date, unless the claim is a correction. */
578	    private BigDecimal floored(String sheetId, Claim claim, BigDecimal due) {
579	        return claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate()));
580	    }
581	
582	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by is
583	     *  before the sheet's today) or a correction, else the late percent of the figure for every 30-day
584	     *  boundary it is overdue past (its due-by plus 30, 60, 90 ... days), the late percent in force on that
585	     *  boundary date of the figure, rounded to two decimals as the claim's date decides (see roundingOf), the
586	     *  charges added up. Never bound by a statement: it follows the
587	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
588	     *  claim as if it were still OPEN. */
589	    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure, boolean open) {
590	        BigDecimal none = BigDecimal.ZERO.setScale(2);
591	        if (!open || claim.isCorrection()) {
592	            return none;
593	        }
594	        long days = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId));
595	        if (days < 30) {
596	            return none;
597	        }
598	        RoundingMode rounding = roundingOf(sheetId, claim);
599	        BigDecimal charge = none;
600	        for (long boundary = 1; boundary <= days / 30; boundary++) {
601	            BigDecimal pct = settings.latePct(sheetId, claim.getDueBy().plusDays(30 * boundary));
602	            if (pct.signum() != 0) {
603	                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
604	            }
605	        }
606	        return charge;
607	    }
608	
609	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
610	     *  on the claim's date: amount times rate
611	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf); the floor is
612	     *  not applied here (see dueOf); null when no rate applies. */
613	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
614	        BigDecimal amount = claim.getAmount();
615	        RoundingMode rounding = roundingOf(sheetId, claim);
616	        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
617	                .map(Rate::getRate)
618	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
619	                .orElse(null);
620	    }
621	
622	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
623	     *  it corrects. */
624	    public LocalDate roundsBy(String sheetId, Claim claim) {
625	        if (!claim.isCorrection() || claim.getCorrects() == null) {
626	            return claim.getDate();
627	        }
628	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
629	                .map(Claim::getDate).orElse(claim.getDate());
630	    }
631	
632	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
633	    private RoundingMode roundingOf(String sheetId, Claim claim) {
634	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
635	    }
636	
637	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
638	     *  is within any limit, and a steward settles anything. */
639	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
640	        BigDecimal limit = settings.clerkLimit(sheetId);
641	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
642	            return false;
643	        }
644	        return settings.roleOf(sheetId, user) == Role.CLERK;
645	    }
646	
647	    /** A claim whose due is above the proof threshold in force on its date cannot be settled or
648	     *  approved while it has no proofs; a due of n/a, or no threshold, asks for none. */
649	    private void refuseUnproved(String sheetId, Claim claim, BigDecimal due) {
650	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
651	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
652	            throw new ProofRequiredException(due, threshold);
653	        }
654	    }
655	
656	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
657	     *  any other amount names none. */
658	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
659	        if (amount.signum() >= 0) {
660	            if (corrects != null) {
661	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
662	            }
663	            return;
664	        }
665	        if (corrects == null) {
666	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
667	        }
668	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
669	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
670	        if (!settled) {
671	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
672	        }
673	    }
674	
675	    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
676	    private void refuseClosed(String sheetId, LocalDate date) {
677	        if (periods.closedOn(sheetId, date)) {
678	            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
679	        }
680	    }
681	
682	    /** A claim dated after its person's retirement date cannot be added or moved there. */
683	    private static void refuseRetired(Person person, LocalDate date) {
684	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
685	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
686	        }
687	    }
688	
689	    private Person person(String sheetId, Long personId) {
690	        return people.findByIdAndSheetId(personId, sheetId)
691	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
692	    }
693	
694	    /** One NOTIFY line for each user watching the claim's person, in the order they started watching. */
695	    private void notifyWatchers(String sheetId, String user, Person person, Claim claim) {
696	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
697	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + user + " user=" + watch.getUser()
698	                    + " person=" + person.getName() + " number=" + claim.getNumber());
699	        }
700	    }
701	
702	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
703	        record(event, sheetId, user, person, claim, claim.getNumber());
704	    }
705	
706	    /** One audit line about a claim; a claim with a number carries it at the end. */
707	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
708	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
709	    }
710	
711	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
712	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
713	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
714	                + (number != null ? " number=" + number : "");
715	    }
716	
717	    private static BigDecimal scaled(BigDecimal amount) {
718	        return amount.setScale(2, RoundingMode.UNNECESSARY);
719	    }
720	
721	    /** A claim number as typed: trimmed, null when blank. */
722	    private static String numberOf(String number) {
723	        return number == null || number.isBlank() ? null : number.trim();
724	    }
725	
726	    private static String noteOf(String note) {
727	        return note == null ? "" : note.trim();
728	    }
729	
730	    /** The terms in days a claim of the person dated on a date takes: the person's own, else their
731	     *  grade's in force then, else the sheet's. */
732	    private int termsFor(String sheetId, Person person, LocalDate on) {
733	        return person.getTerms() != null ? person.getTerms()
734	                : settings.termsFor(sheetId, grades.gradeOn(person.getId(), on), on);
735	    }
736	}
